package com.fintrack.khmtomnenh.quotationitem.entity; import com.fasterxml.jackson.annotation.*; import com.fintrack.khmtomnenh.product.entity.Product; import com.fintrack.khmtomnenh.quotation.entity.Quotation; import jakarta.persistence.*; import lombok.*; import java.math.*;
